export interface BrandIconProps extends SVGProps<SVGSVGElement> {
  name:
    | "app-logo"
    | "nextjs"
    | "adobe"
    | "astro"
    | "embla"
    | "github"
    | "inertia.js"
    | "laravel"
    | "tanstack-start"
    | "remix"
    | "tailwind"
    | "vite"
    | "motion"
    | "bun"
    | "npm"
    | "pnpm"
    | "yarn"
    | "lucide"
    | "tabler"
    | "remixicon"
    | "phosphor"
    | "hugeicons"
}

export const BrandIcon = ({ name, ...props }: BrandIconProps) => {
  switch (name) {
    case "app-logo":
      return <IconApp {...props} />
    case "nextjs":
      return <IconBrandNextjs {...props} />
    case "adobe":
      return <IconBrandAdobe {...props} />
    case "astro":
      return <IconBrandAstro {...props} />
    case "embla":
      return <IconBrandEmbla {...props} />
    case "github":
      return <IconBrandGithub {...props} />
    case "inertia.js":
      return <IconBrandInertia {...props} />
    case "laravel":
      return <IconBrandLaravel {...props} />
    case "tanstack-start":
      return <IconBrandTanstackStart {...props} />
    case "remix":
      return <IconBrandRemix {...props} />
    case "tailwind":
      return <IconBrandTailwind {...props} />
    case "vite":
      return <IconBrandVite {...props} />
    case "motion":
      return <IconBrandMotion {...props} />
    case "bun":
      return <IconBrandBun {...props} />
    case "npm":
      return <IconBrandNpm {...props} />
    case "pnpm":
      return <IconBrandPnpm {...props} />
    case "yarn":
      return <IconBrandYarn {...props} />
    case "tabler":
      return <IconBrandTabler {...props} />
    default:
      return <IconCircleDot {...props} />
  }
}

